function verifySig(
    address _signer,
    bytes32 _theHash,
    ValSignature memory _sig
) private pure returns (bool) {
    bytes32 messageDigest =
        keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", _theHash));
    return _signer == ecrecover(messageDigest, _sig.v, _sig.r, _sig.s);
}

